import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.extern .shared .align 16 .b8 smem[];
.visible .entry convt3d_kernel(
    .param .u64 p_input,
    .param .u64 p_weight,
    .param .u64 p_output,
    .param .u32 pN,
    .param .u32 pCin,
    .param .u32 pCout,
    .param .u32 pDin,
    .param .u32 pHin,
    .param .u32 pWin,
    .param .u32 pKd,
    .param .u32 pKh,
    .param .u32 pKw,
    .param .u32 pDout,
    .param .u32 pHout,
    .param .u32 pWout
)
{
    .reg .pred  %p<40>;
    .reg .b32   %r<180>;
    .reg .b64   %rd<130>;
    .reg .f32   %f<8>;
    .reg .b64   %rd_pre0;
    .reg .b64   %rd_pre1;
    .reg .b64   %rd_cur0;
    .reg .b64   %rd_cur1;
    // Load params
    ld.param.u64    %rd10, [p_input];
    ld.param.u64    %rd11, [p_weight];
    ld.param.u64    %rd12, [p_output];
    ld.param.u32    %r10, [pN];
    ld.param.u32    %r11, [pCin];
    ld.param.u32    %r12, [pCout];
    ld.param.u32    %r13, [pDin];
    ld.param.u32    %r14, [pHin];
    ld.param.u32    %r15, [pWin];
    ld.param.u32    %r16, [pKd];
    ld.param.u32    %r17, [pKh];
    ld.param.u32    %r18, [pKw];
    ld.param.u32    %r19, [pDout];
    ld.param.u32    %r20, [pHout];
    ld.param.u32    %r21, [pWout];
    // Thread/block info
    mov.u32         %r30, %tid.x;
    mov.u32         %r31, %ntid.x;
    mov.u32         %r32, %ctaid.x;
    // gid = blockIdx.x * blockDim.x + threadIdx.x
    mad.lo.s32      %r33, %r32, %r31, %r30;
    // total = N * Cout * Dout * Hout * Wout
    mul.lo.u32      %r40, %r10, %r12;      // N*Cout
    mul.lo.u32      %r41, %r19, %r20;      // Dout*Hout
    mul.lo.u32      %r42, %r41, %r21;      // Dout*Hout*Wout
    mul.lo.u32      %r43, %r40, %r42;      // total
    add.u32         %r44, %r43, 0xffffffff; // total-1
    // Active predicate: gid < total
    setp.lt.u32     %p0, %r33, %r43;
    // Block base gid and last gid in block (clamped)
    mul.lo.u32      %r70, %r32, %r31;      // block_base = ctaid.x * ntid.x
    add.u32         %r71, %r70, %r31;      // base + blockDim
    add.u32         %r71, %r71, 0xffffffff; // -1 => last index (unclamped)
    setp.gt.u32     %p1, %r71, %r44;
    selp.u32        %r72, %r71, %r44, %p1; // gid_last = min(last, total-1)
    // Derive oc0 for this CTA from block_base and spatial, and set oc_next=(oc0+1)%Cout
    // oc0 = ((block_base / spatial) % Cout)
    div.u32         %r102, %r70, %r42;    // n*Cout + oc0
    rem.u32         %r76, %r102, %r12;    // oc0
    // oc_next = (oc0 + 1) % Cout
    add.u32         %r80, %r76, 1;
    setp.eq.u32     %p19, %r80, %r12;
    selp.u32        %r80, 0, %r80, %p19;  // oc_next
    // K dims
    mul.lo.u32      %r81, %r17, %r18;      // Kh*Kw
    mul.lo.u32      %r82, %r16, %r81;      // K = Kd*Kh*Kw
    // Shared memory base and offsets for two oc's with double-buffering
    mov.u64         %rd40, smem;              // base
    mul.wide.u32    %rd41, %r82, 4;        // K * 4
    add.s64         %rd42, %rd40, 0;       // s0 bank0
    add.s64         %rd43, %rd40, %rd41;   // s0 bank1
    mul.wide.u32    %rd70, %r82, 8;        // 2*K*4
    add.s64         %rd90, %rd40, %rd70;   // s1 bank0
    add.s64         %rd91, %rd90, %rd41;   // s1 bank1
    // Thread-specific decode for active threads
    @%p0 bra        L_decode_active;
    // If inactive, zero out output ptr to avoid accidental use
    mov.u32         %r50, 0;   // xo
    mov.u32         %r52, 0;   // yo
    mov.u32         %r54, 0;   // zo
    mov.u32         %r56, 0;   // oc
    mov.u32         %r57, 0;   // n
    mov.u64         %rd21, 0;  // out addr
    bra             L_decode_done;
L_decode_active:
    // Decode gid into (xo, yo, zo, oc, n)
    rem.u32         %r50, %r33, %r21;      // xo
    div.u32         %r51, %r33, %r21;      // t1
    rem.u32         %r52, %r51, %r20;      // yo
    div.u32         %r53, %r51, %r20;      // t2
    rem.u32         %r54, %r53, %r19;      // zo
    div.u32         %r55, %r53, %r19;      // t3
    rem.u32         %r56, %r55, %r12;      // oc
    div.u32         %r57, %r55, %r12;      // n
    // Prepare output address: out_ptr + gid * 4
    mul.wide.u32    %rd20, %r33, 4;
    add.s64         %rd21, %rd12, %rd20;
L_decode_done:
    // Prepare oc predicate once (oc == oc0 ?)
    setp.eq.u32     %p2, %r56, %r76;
    // Accumulator
    mov.f32         %f0, 0f00000000;
    // ic loop with cp.async double-buffered weight staging
    mov.u32         %r60, 0;               // ic = 0
    mov.u32         %r120, 0;              // stage flag s = 0
    // Preload ic=0 into stage 0
    mov.u32         %r83, %r30;            // load_idx = threadIdx.x
    // Vectorized stage-0 preload: copy 16B chunks where possible
    // Scalar async preload for stage-0 (4B transactions, alignment-safe)
    mov.u32         %r83, %r30;            // idx = threadIdx.x
L_pre0_vec:
    setp.ge.u32     %p4, %r83, %r82;
    @%p4 bra        L_pre0_end;
      // Compute global and shared addresses for oc0
      mul.lo.u32      %r171, %r60, %r12;        // ic*Cout
      add.u32         %r171, %r171, %r76;       // + oc0
      mul.lo.u32      %r172, %r171, %r82;       // *K
      add.u32         %r172, %r172, %r83;       // + idx
      mul.wide.u32    %rd44, %r172, 4;
      add.s64         %rd45, %rd11, %rd44;
      // Shared dest for stage0 bank0
      mul.wide.u32    %rd46, %r83, 4;
      add.s64         %rd47, %rd42, %rd46;
      cp.async.ca.shared.global [%rd47], [%rd45], 4;
      // Compute global and shared addresses for oc_next
      mul.lo.u32      %r173, %r60, %r12;
      add.u32         %r173, %r173, %r80;
      mul.lo.u32      %r174, %r173, %r82;
      add.u32         %r174, %r174, %r83;
      mul.wide.u32    %rd48, %r174, 4;
      add.s64         %rd49, %rd11, %rd48;
      add.s64         %rd52, %rd43, %rd46;
      cp.async.ca.shared.global [%rd52], [%rd49], 4;
      // Next index
      add.u32         %r83, %r83, %r31;
      bra             L_pre0_vec;
L_pre0_end:
    cp.async.commit_group;
    cp.async.wait_group 0;
    bar.sync 0;
L_ic:
    setp.ge.u32     %p3, %r60, %r11;
    @%p3 bra        L_ic_end;
    // Preload next ic into the other stage if available
    add.u32         %r110, %r60, 1;       // next_ic
    setp.lt.u32     %p20, %r110, %r11;
    @!%p20 bra      L_no_pre;
      // Vectorized prefetch into opposite stage: copy 16B chunks where possible
      setp.eq.u32     %p21, %r120, 0;
      selp.b64        %rd_pre0, %rd90, %rd42, %p21; // if s==0 -> s1 else s0
      selp.b64        %rd_pre1, %rd91, %rd43, %p21;
      // Scalar async prefetch into opposite stage (4B transactions, alignment-safe)
      mov.u32         %r83, %r30;              // idx = threadIdx.x
    L_preN_vec:
      setp.ge.u32     %p4, %r83, %r82;
      @%p4 bra        L_preN_end;
        // oc0 at next_ic
        mul.lo.u32      %r171, %r110, %r12;        // next_ic*Cout
        add.u32         %r171, %r171, %r76;        // + oc0
        mul.lo.u32      %r172, %r171, %r82;        // *K
        add.u32         %r172, %r172, %r83;        // + idx
        mul.wide.u32    %rd53, %r172, 4;
        add.s64         %rd54, %rd11, %rd53;
        // dest in selected prefetch stage bank0
        mul.wide.u32    %rd55, %r83, 4;
        add.s64         %rd56, %rd_pre0, %rd55;
        cp.async.ca.shared.global [%rd56], [%rd54], 4;
        // oc_next at next_ic
        mul.lo.u32      %r173, %r110, %r12;
        add.u32         %r173, %r173, %r80;
        mul.lo.u32      %r174, %r173, %r82;
        add.u32         %r174, %r174, %r83;
        mul.wide.u32    %rd57, %r174, 4;
        add.s64         %rd58, %rd11, %rd57;
        add.s64         %rd59, %rd_pre1, %rd55;
        cp.async.ca.shared.global [%rd59], [%rd58], 4;
        // next index
        add.u32         %r83, %r83, %r31;
        bra             L_preN_vec;
    L_preN_end:
      cp.async.commit_group;
    L_no_pre:
    // Select per-thread weight base for current stage
    setp.eq.u32     %p22, %r120, 0;
    selp.b64        %rd_cur0, %rd42, %rd90, %p22; // if s==0 -> s0 else s1
    selp.b64        %rd_cur1, %rd43, %rd91, %p22;
    selp.b64        %rd50, %rd_cur0, %rd_cur1, %p2; // rd50 = base for this thread
    // Only active threads perform accumulation
    @!%p0 bra       L_after_compute;
    // Loop over kz
    mov.u32         %r61, 0;               // kz = 0
L_kz:
    setp.ge.u32     %p5, %r61, %r16;
    @%p5 bra        L_kz_end;
    // zi = zo - kz
    sub.s32         %r62, %r54, %r61;
    setp.lt.s32     %p6, %r62, 0;
    setp.ge.s32     %p7, %r62, %r13;
    or.pred         %p8, %p6, %p7;
    @%p8 bra        L_kz_next;
    // Loop over ky
    mov.u32         %r63, 0;               // ky = 0
L_ky:
    setp.ge.u32     %p9, %r63, %r17;
    @%p9 bra        L_ky_end;
    // yi = yo - ky
    sub.s32         %r64, %r52, %r63;
    setp.lt.s32     %p10, %r64, 0;
    setp.ge.s32     %p11, %r64, %r14;
    or.pred         %p12, %p10, %p11;
    @%p12 bra       L_ky_next;
    // Loop over kx
    mov.u32         %r65, 0;               // kx = 0
    // Precompute base pointers for inner kx loop
    // Compute input row base pointer for (n, ic, zi, yi) and xi=xo
    mul.lo.u32      %r130, %r57, %r11;     // n*Cin
    add.u32         %r130, %r130, %r60;    // + ic
    mad.lo.u32      %r131, %r130, %r13, %r62; // *Din + zi
    mad.lo.u32      %r132, %r131, %r14, %r64; // *Hin + yi
    mul.lo.u32      %r133, %r132, %r15;   // *Win
    add.u32         %r134, %r133, %r50;   // + xo
    mul.wide.u32    %rd100, %r134, 4;
    add.s64         %rd101, %rd10, %rd100; // rd_in_cur
    // Compute shared weight pointer base for (kz,ky,kx=0)
    mul.lo.u32      %r135, %r61, %r81;     // kz*(Kh*Kw)
    mad.lo.u32      %r135, %r63, %r18, %r135; // + ky*Kw
    mul.wide.u32    %rd102, %r135, 4;
    add.s64         %rd103, %rd50, %rd102; // rd_w_cur
L_kx:
    setp.ge.u32     %p13, %r65, %r18;
    @%p13 bra       L_kx_end;
    // If remaining < 4, go to tail scalar loop
    sub.u32         %r160, %r18, %r65;
    setp.lt.u32     %p30, %r160, 4;
    @%p30 bra       L_kx_tail;
    // Unrolled by 4 over kx
    // Base xi for current kx
    sub.s32         %r66, %r50, %r65;
    // oob checks for xi, xi-1, xi-2, xi-3
    setp.lt.s32     %p14, %r66, 0;
    setp.ge.s32     %p15, %r66, %r15;
    or.pred         %p16, %p14, %p15;         // oob0
    add.s32         %r161, %r66, 0xffffffff;  // xi-1
    setp.lt.s32     %p31, %r161, 0;
    setp.ge.s32     %p32, %r161, %r15;
    or.pred         %p33, %p31, %p32;         // oob1
    add.s32         %r162, %r66, 0xfffffffe;  // xi-2
    setp.lt.s32     %p34, %r162, 0;
    setp.ge.s32     %p35, %r162, %r15;
    or.pred         %p36, %p34, %p35;         // oob2
    add.s32         %r163, %r66, 0xfffffffd;  // xi-3
    setp.lt.s32     %p37, %r163, 0;
    setp.ge.s32     %p38, %r163, %r15;
    or.pred         %p39, %p37, %p38;         // oob3
    // Load 4 weights
    ld.shared.f32   %f4, [%rd103];
    add.s64         %rd104, %rd103, 4;
    ld.shared.f32   %f5, [%rd104];
    add.s64         %rd105, %rd104, 4;
    ld.shared.f32   %f6, [%rd105];
    add.s64         %rd106, %rd105, 4;
    ld.shared.f32   %f7, [%rd106];
    // Step 0
    @%p16 bra       L_skip0;
      ld.global.f32   %f3, [%rd101];
      fma.rn.f32      %f0, %f3, %f4, %f0;
    L_skip0:
    // Step 1
    add.s64         %rd107, %rd101, -4;
    @%p33 bra       L_skip1;
      ld.global.f32   %f3, [%rd107];
      fma.rn.f32      %f0, %f3, %f5, %f0;
    L_skip1:
    // Step 2
    add.s64         %rd108, %rd101, -8;
    @%p36 bra       L_skip2;
      ld.global.f32   %f3, [%rd108];
      fma.rn.f32      %f0, %f3, %f6, %f0;
    L_skip2:
    // Step 3
    add.s64         %rd109, %rd101, -12;
    @%p39 bra       L_skip3;
      ld.global.f32   %f3, [%rd109];
      fma.rn.f32      %f0, %f3, %f7, %f0;
    L_skip3:
    // Advance pointers and counters
    add.u32         %r65, %r65, 4;
    add.s64         %rd103, %rd103, 16;   // advance weight ptr
    add.s64         %rd101, %rd101, -16;  // move input ptr left by 4
    bra             L_kx;
L_kx_tail:
    setp.ge.u32     %p13, %r65, %r18;
    @%p13 bra       L_kx_end;
    // xi = xo - kx
    sub.s32         %r66, %r50, %r65;
    setp.lt.s32     %p14, %r66, 0;
    setp.ge.s32     %p15, %r66, %r15;
    or.pred         %p16, %p14, %p15;
    // Load weight for this (kz,ky,kx) from shared memory
    ld.shared.f32   %f4, [%rd103];
    // Conditionally load input and FMA accumulate when in-bounds
    @%p16 bra       L_skip_fma;
      ld.global.f32   %f3, [%rd101];
      fma.rn.f32      %f0, %f3, %f4, %f0;
L_skip_fma:
L_kx_next:
    add.u32         %r65, %r65, 1;
    add.s64         %rd103, %rd103, 4;   // advance weight ptr
    add.s64         %rd101, %rd101, -4;  // move input ptr left (xi-1)
    bra             L_kx_tail;
L_kx_end:
L_ky_next:
    add.u32         %r63, %r63, 1;
    bra             L_ky;
L_ky_end:
L_kz_next:
    add.u32         %r61, %r61, 1;
    bra             L_kz;
L_kz_end:
L_after_compute:
    // Ensure all threads done using shared weights before next ic and wait for prefetch
    bar.sync 0;
    cp.async.wait_group 0;
    // Next ic and flip stage
    add.u32         %r60, %r60, 1;
    xor.b32         %r120, %r120, 1;
    bra             L_ic;
L_ic_end:
    // Store result (only active)
    @!%p0 bra       RET;
    st.global.f32   [%rd21], %f0;
RET:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("convt3d_kernel")

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: tuple = (1, 1, 1), padding: tuple = (0, 0, 0), output_padding: tuple = (0, 0, 0), groups: int = 1, bias: bool = False):
        super().__init__()
        if groups != 1:
            raise NotImplementedError("groups != 1 not supported")
        if stride != (1, 1, 1):
            raise NotImplementedError("Only stride=(1,1,1) supported")
        if padding != (0, 0, 0):
            raise NotImplementedError("Only padding=(0,0,0) supported")
        if output_padding != (0, 0, 0):
            raise NotImplementedError("Only output_padding=(0,0,0) supported")
        if bias:
            raise NotImplementedError("bias=True not supported")
        kd, kh, kw = kernel_size
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = (kd, kh, kw)
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups
        self.bias = None
        # Weight layout matches nn.ConvTranspose3d: (in_channels, out_channels, kd, kh, kw)
        w = torch.empty(in_channels, out_channels, kd, kh, kw)
        nn.init.kaiming_uniform_(w, a=5 ** 0.5)
        self.weight = nn.Parameter(w)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            raise RuntimeError("Input must be a CUDA tensor")
        if x.dtype != torch.float32:
            raise NotImplementedError("Only float32 supported")
        if not x.is_contiguous():
            x = x.contiguous()
        N, Cin, Din, Hin, Win = x.shape
        assert Cin == self.in_channels, "Input channels mismatch"

        kd, kh, kw = self.kernel_size
        # For stride=1, padding=0, output_padding=0, dilation=1:
        Dout = Din + kd - 1
        Hout = Hin + kh - 1
        Wout = Win + kw - 1

        out = torch.empty((N, self.out_channels, Dout, Hout, Wout), device=x.device, dtype=x.dtype)

        # Ensure weight is on the same device and contiguous
        w = self.weight
        if not w.is_contiguous():
            w = w.contiguous()
        if w.device != x.device:
            w = w.to(device=x.device)

        total = N * self.out_channels * Dout * Hout * Wout
        spatial = Dout * Hout * Wout
        block_x = min(256, spatial)
        grid_x = (total + block_x - 1) // block_x
        module = _get_ptx_module()
        smem_bytes = 4 * kd * kh * kw * 4
        module.launch(
            "convt3d_kernel",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[
                x, w, out,
                i32(N), i32(Cin), i32(self.out_channels),
                i32(Din), i32(Hin), i32(Win),
                i32(kd), i32(kh), i32(kw),
                i32(Dout), i32(Hout), i32(Wout),
            ],
            shared_memory=smem_bytes,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

