import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.extern .shared .align 16 .b8 smem[];
.visible .entry convt3d_kernel(
    .param .u64 p_input,
    .param .u64 p_weight,
    .param .u64 p_output,
    .param .u32 pN,
    .param .u32 pCin,
    .param .u32 pCout,
    .param .u32 pDin,
    .param .u32 pHin,
    .param .u32 pWin,
    .param .u32 pKd,
    .param .u32 pKh,
    .param .u32 pKw,
    .param .u32 pDout,
    .param .u32 pHout,
    .param .u32 pWout
)
{
    .reg .pred  %p<40>;
    .reg .b32   %r<180>;
    .reg .b64   %rd<130>;
    .reg .f32   %f<8>;
    .reg .b64   %rd_pre0;
    .reg .b64   %rd_pre1;
    .reg .b64   %rd_cur0;
    .reg .b64   %rd_cur1;
    // Load params
    ld.param.u64    %rd10, [p_input];
    ld.param.u64    %rd11, [p_weight];
    ld.param.u64    %rd12, [p_output];
    ld.param.u32    %r10, [pN];
    ld.param.u32    %r11, [pCin];
    ld.param.u32    %r12, [pCout];
    ld.param.u32    %r13, [pDin];
    ld.param.u32    %r14, [pHin];
    ld.param.u32    %r15, [pWin];
    ld.param.u32    %r16, [pKd];
    ld.param.u32    %r17, [pKh];
    ld.param.u32    %r18, [pKw];
    ld.param.u32    %r19, [pDout];
    ld.param.u32    %r20, [pHout];
    ld.param.u32    %r21, [pWout];
    // Thread/block info
    mov.u32         %r30, %tid.x;
    mov.u32         %r31, %ntid.x;
    mov.u32         %r32, %ctaid.x;
